insert into public.driving_rule_topics (topic_code, title_de, title_en, reviewed_on) values
  ('lez', 'Umweltzone und Feinstaubplakette', 'Low-emission zones and the Feinstaubplakette', '2026-09-19'::date),
  ('speed', 'Geschwindigkeiten', 'Speed limits', '2026-09-19'::date),
  ('winter', 'Winterreifen', 'Winter tyres', '2026-09-19'::date),
  ('alcohol', 'Alkohol und Drogen am Steuer', 'Alcohol and drugs', '2026-09-19'::date),
  ('toll', 'Maut', 'Tolls', '2026-09-19'::date),
  ('truck_ban', 'Sonntags- und Feiertagsfahrverbot für Lkw', 'Sunday and holiday lorry ban', '2026-10-08'::date),
  ('equipment', 'Was ins Auto gehört', 'What the law requires in the car', '2026-09-19'::date),
  ('emergency', 'Notruf, Rettungsgasse, Panne und Unfall', 'Emergency numbers, rescue lane, breakdown and crash', '2026-09-19'::date),
  ('ev', 'Elektroauto fahren und laden', 'Driving and charging an electric car', '2026-09-19'::date);
insert into public.driving_rule_facts (fact_key, topic_code, position, body_de, body_en, source_url, source_name, source_note_de, source_note_en, to_verify_de, to_verify_en, reviewed_on, headline) values
  ('lez.zones_exist', 'lez', 1, 'Viele deutsche Städte haben eine Umweltzone: hineinfahren darf nur, wer eine gültige Feinstaubplakette sichtbar an der Windschutzscheibe hat — ausländische Fahrzeuge eingeschlossen.', 'Many German cities have a low-emission zone (Umweltzone): you may only drive in with a valid Feinstaubplakette displayed on the windscreen — foreign vehicles included.', 'https://www.gesetze-im-internet.de/bimschv_35_2007/', '35. BImSchV', null, null, null, null, '2026-09-19'::date, true),
  ('lez.green_only', 'lez', 2, 'Praktisch alle ausgeschilderten Umweltzonen verlangen heute die grüne Plakette (Schadstoffgruppe 4). Das Zusatzzeichen unter dem Schild sagt verbindlich, welche Plakette gilt.', 'In practice every signposted Umweltzone today requires the green plaque (emission group 4). The supplementary sign under the zone sign is what actually decides which plaque applies.', 'https://www.umweltbundesamt.de/themen/luft/luftschadstoffe/feinstaub/umweltzonen-in-deutschland', 'Umweltbundesamt, Umweltzonen in Deutschland', null, null, 'ob irgendwo noch eine einzelne Zone gelbe oder rote Plaketten zulässt — im Zweifel gilt das Zusatzzeichen', 'whether any single zone still admits yellow or red plaques — if in doubt, the supplementary sign decides', '2026-09-19'::date, false),
  ('lez.where_to_buy', 'lez', 3, 'Die Plakette gibt es bei Kfz-Zulassungsstellen, technischen Prüfstellen und Überwachungsorganisationen (TÜV, DEKRA, GTÜ, KÜS) und anerkannten Werkstätten. Mitbringen: die Zulassungsbescheinigung Teil I bzw. den ausländischen Fahrzeugschein. Sie gilt unbefristet und klebt fahrzeuggebunden.', 'You get the plaque at vehicle registration offices, technical inspection bodies (TÜV, DEKRA, GTÜ, KÜS) and approved garages. Bring the vehicle registration document (part I) or its foreign equivalent. It does not expire and belongs to that one vehicle.', 'https://www.gesetze-im-internet.de/bimschv_35_2007/', '§ 3 35. BImSchV', null, null, null, null, '2026-09-19'::date, false),
  ('lez.price', 'lez', 4, 'Die Gebühr liegt an der Ausgabestelle üblicherweise im niedrigen einstelligen Euro-Bereich; Online-Händler verlangen deutlich mehr.', 'At an issuing office the fee is usually a few euros; online resellers charge considerably more.', 'https://www.gesetze-im-internet.de/bimschv_35_2007/', '35. BImSchV, Gebühr der Ausgabestelle', null, null, 'der genaue Gebührenrahmen je Ausgabestelle', 'the exact fee charged per issuing office', '2026-09-19'::date, false),
  ('lez.penalty', 'lez', 5, 'Ohne gültige Plakette in die Umweltzone zu fahren kostet ein Bußgeld in der Größenordnung von 100 €.', 'Entering the zone without a valid plaque costs a fine in the order of €100.', 'https://www.gesetze-im-internet.de/bkatv_2013/', 'Bußgeldkatalog-Verordnung (BKatV)', null, null, 'der genaue Betrag im aktuellen Bußgeldkatalog', 'the exact amount in the current fines catalogue', '2026-09-19'::date, false),
  ('lez.foreign_stickers', 'lez', 6, 'Eine französische Crit''Air-Vignette oder eine andere ausländische Umweltplakette gilt in Deutschland nicht — es zählt allein die deutsche Feinstaubplakette.', 'A French Crit''Air sticker or any other foreign environmental badge is not valid in Germany — only the German Feinstaubplakette counts.', 'https://www.umweltbundesamt.de/themen/luft/luftschadstoffe/feinstaub/umweltzonen-in-deutschland', 'Umweltbundesamt, Umweltzonen in Deutschland', null, null, null, null, '2026-09-19'::date, false),
  ('lez.signage', 'lez', 7, 'Die Zone beginnt am Zeichen 270.1 und endet am Zeichen 270.2; das Zusatzzeichen darunter zeigt die zugelassenen Plaketten.', 'The zone starts at sign 270.1 and ends at sign 270.2; the plate underneath shows which plaques are admitted.', 'https://www.gesetze-im-internet.de/stvo_2013/anlage_2.html', 'StVO Anlage 2, Zeichen 270.1 / 270.2', null, null, null, null, '2026-09-19'::date, false),
  ('lez.diesel_bans', 'lez', 8, 'Einzelne Städte hatten zusätzlich Diesel-Durchfahrtsverbote, die unabhängig von der Plakette gelten und sich mehrfach geändert haben — vor der Fahrt auf der Seite der Stadt prüfen.', 'Some cities additionally had diesel through-traffic bans that apply regardless of the plaque and have changed repeatedly — check the city''s own page before you drive.', 'https://www.umweltbundesamt.de/themen/luft/luftschadstoffe/feinstaub/umweltzonen-in-deutschland', 'Umweltbundesamt, Umweltzonen in Deutschland', null, null, 'welche Diesel-Verbote heute noch in Kraft sind (u. a. Stuttgart, München, Hamburg)', 'which diesel bans are still in force today (Stuttgart, Munich, Hamburg among others)', '2026-09-19'::date, false),
  ('speed.autobahn', 'speed', 1, 'Auf Autobahnen gibt es kein allgemeines Tempolimit, wo kein Schild etwas anderes anordnet; empfohlen ist die Richtgeschwindigkeit 130 km/h. Wer schneller fährt, kann bei einem Unfall mithaften.', 'On the Autobahn there is no general speed limit where no sign says otherwise; the advisory speed is 130 km/h. Drive faster and you can share liability in a crash.', 'https://www.gesetze-im-internet.de/autobahnrichtgv/', 'Autobahn-Richtgeschwindigkeits-V', null, null, null, null, '2026-09-19'::date, true),
  ('speed.built_up', 'speed', 2, 'Innerorts 50 km/h, wenn nichts anderes angeordnet ist — viele Wohnstraßen sind Tempo-30-Zonen.', '50 km/h in built-up areas unless signed otherwise — many residential streets are 30 km/h zones.', 'https://www.gesetze-im-internet.de/stvo_2013/__3.html', '§ 3 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('speed.rural', 'speed', 3, 'Außerorts 100 km/h für Pkw und Krafträder.', '100 km/h for cars and motorcycles on roads outside built-up areas.', 'https://www.gesetze-im-internet.de/stvo_2013/__3.html', '§ 3 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('speed.trailer_truck', 'speed', 4, 'Pkw mit Anhänger und Fahrzeuge über 3,5 t: 80 km/h, auch auf der Autobahn (Lkw über 7,5 t außerorts 60 km/h, auf der Autobahn 80 km/h).', 'Car with trailer and vehicles over 3.5 t: 80 km/h, on the Autobahn too (lorries over 7.5 t: 60 km/h on rural roads, 80 km/h on the Autobahn).', 'https://www.gesetze-im-internet.de/stvo_2013/__3.html', '§ 3 StVO', null, null, 'ob die deutsche Tempo-100-Zulassung für Gespanne auf ausländisch zugelassene Gespanne anwendbar ist', 'whether the German 100 km/h trailer approval can apply to a foreign-registered combination', '2026-09-19'::date, false),
  ('speed.radar_apps', 'speed', 5, 'Blitzerwarner — Gerät oder App — dürfen während der Fahrt nicht betriebsbereit mitgeführt oder benutzt werden. Feste und mobile Kontrollen sind häufig.', 'Speed-camera warners — device or app — must not be used or kept ready while driving. Fixed and mobile enforcement is common.', 'https://www.gesetze-im-internet.de/stvo_2013/__23.html', '§ 23 Abs. 1c StVO', null, null, null, null, '2026-09-19'::date, false),
  ('speed.cross_border_fines', 'speed', 6, 'Bußgelder werden innerhalb der EU grenzüberschreitend vollstreckt — ein Bescheid erreicht Sie auch zu Hause.', 'Fines are enforced across EU borders — a notice will reach you at home.', 'https://www.gesetze-im-internet.de/bkatv_2013/', 'BKatV; EU-Rahmenbeschluss zur Vollstreckung von Geldsanktionen', null, null, 'die Bagatellgrenze, ab der vollstreckt wird (häufig 70 € inkl. Kosten genannt)', 'the de-minimis threshold for enforcement (often quoted as €70 including costs)', '2026-09-19'::date, false),
  ('winter.situational', 'winter', 1, 'Deutschland hat keine Winterreifenpflicht nach Kalender, sondern eine situative: bei Glatteis, Schneeglätte, Schneematsch, Eis- oder Reifglätte darf ein Kraftfahrzeug nur mit Winterreifen gefahren werden. Im November ohne solche Verhältnisse ist es also erlaubt — mit ihnen nicht.', 'Germany has no calendar-based winter-tyre rule but a situational one: in black ice, packed snow, slush, ice or frost you may only drive on winter tyres. So in November without those conditions you may drive; with them you may not.', 'https://www.gesetze-im-internet.de/stvo_2013/__2.html', '§ 2 Abs. 3a StVO', null, null, null, null, '2026-09-19'::date, true),
  ('winter.alpine_symbol', 'winter', 2, 'Als Winterreifen zählt nur noch der Reifen mit dem Alpine-Symbol (Schneeflocke im Berg, 3PMSF); die Übergangsfrist für reine M+S-Reifen ist zum 30. September 2024 ausgelaufen.', 'Only tyres carrying the Alpine symbol (snowflake in a mountain, 3PMSF) count as winter tyres; the transition period for M+S-only tyres ended on 30 September 2024.', 'https://www.gesetze-im-internet.de/stvo_2013/__2.html', '§ 2 Abs. 3a StVO i. V. m. § 36 StVZO', null, null, null, null, '2026-09-19'::date, false),
  ('winter.all_season', 'winter', 3, 'Ganzjahresreifen mit Alpine-Symbol erfüllen die Pflicht; Sommerreifen mit Schneeketten nicht.', 'All-season tyres with the Alpine symbol satisfy the duty; summer tyres plus snow chains do not.', 'https://www.gesetze-im-internet.de/stvo_2013/__2.html', '§ 2 Abs. 3a StVO', null, null, null, null, '2026-09-19'::date, false),
  ('winter.rule_of_thumb', 'winter', 4, 'Die Faustregel „von O bis O“ (Oktober bis Ostern) ist ein Rat, keine Vorschrift — im Mietwagen trotzdem nachfragen, womit das Auto bereift ist.', 'The rule of thumb "O to O" (October to Easter) is advice, not law — in a rental car ask anyway which tyres are fitted.', 'https://www.gesetze-im-internet.de/stvo_2013/__2.html', '§ 2 Abs. 3a StVO', 'die Faustregel steht dort nicht', 'the rule of thumb is not in it', null, null, '2026-09-19'::date, false),
  ('winter.penalty', 'winter', 5, 'Bei winterlichen Verhältnissen ohne Winterreifen zu fahren kostet Bußgeld und einen Punkt; wer andere behindert, zahlt mehr, und der Halter haftet zusätzlich.', 'Driving in winter conditions without winter tyres costs a fine and a point; obstructing others costs more, and the keeper is liable on top.', 'https://www.gesetze-im-internet.de/bkatv_2013/', 'Bußgeldkatalog-Verordnung (BKatV)', null, null, 'die genauen Beträge für Fahrer und Halter', 'the exact amounts for driver and keeper', '2026-09-19'::date, false),
  ('winter.chains', 'winter', 6, 'Schneeketten sind nur dort vorgeschrieben, wo Zeichen 268 steht; dann gilt dort höchstens 50 km/h.', 'Snow chains are compulsory only where sign 268 stands; there the maximum speed is then 50 km/h.', 'https://www.gesetze-im-internet.de/stvo_2013/anlage_2.html', 'StVO Anlage 2, Zeichen 268', null, null, null, null, '2026-09-19'::date, false),
  ('winter.clear_the_car', 'winter', 7, 'Vor dem Losfahren Schnee und Eis vom ganzen Fahrzeug räumen, auch vom Dach und von den Kennzeichen — ein freigekratztes Guckloch genügt nicht.', 'Clear snow and ice from the whole car before driving, roof and number plates included — a scraped peephole is not enough.', 'https://www.gesetze-im-internet.de/stvo_2013/__23.html', '§ 23 Abs. 1 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('winter.speed_rating', 'winter', 8, 'Winterreifen mit geringerer Geschwindigkeitsfreigabe als die Höchstgeschwindigkeit des Autos brauchen einen Hinweis im Sichtfeld der Fahrerin.', 'Winter tyres rated below the car''s top speed require a reminder sticker in the driver''s field of view.', 'https://www.gesetze-im-internet.de/stvzo_2012/__36.html', '§ 36 StVZO', null, null, null, null, '2026-09-19'::date, false),
  ('alcohol.limit', 'alcohol', 1, 'Die Grenze liegt bei 0,5 Promille: ab 0,5 ‰ drohen Bußgeld, Fahrverbot und Punkte.', 'The limit is 0.5 per mille: from 0.5 ‰ you face a fine, a driving ban and points.', 'https://www.gesetze-im-internet.de/stvg/__24a.html', '§ 24a StVG', null, null, null, null, '2026-09-19'::date, true),
  ('alcohol.novice', 'alcohol', 2, '0,0 Promille für Fahranfänger in der Probezeit und für alle unter 21 Jahren — unabhängig davon, wo der Führerschein ausgestellt wurde.', '0.0 per mille for novice drivers in the probationary period and for everyone under 21 — whatever country issued the licence.', 'https://www.gesetze-im-internet.de/stvg/__24c.html', '§ 24c StVG', null, null, null, null, '2026-09-19'::date, false),
  ('alcohol.criminal', 'alcohol', 3, 'Ab 1,1 ‰ gilt absolute Fahruntüchtigkeit — das ist eine Straftat. Schon ab 0,3 ‰ wird es strafbar, wenn Ausfallerscheinungen oder ein Unfall dazukommen.', 'From 1.1 ‰ you are legally unfit to drive — a criminal offence. From as little as 0.3 ‰ it becomes criminal if you drive erratically or cause a crash.', 'https://www.gesetze-im-internet.de/stgb/__316.html', '§ 316 StGB', null, null, null, null, '2026-09-19'::date, false),
  ('alcohol.penalty', 'alcohol', 4, 'Der erste Verstoß über 0,5 ‰ kostet mehrere hundert Euro, einen Monat Fahrverbot und Punkte.', 'A first offence above 0.5 ‰ costs several hundred euros, a one-month driving ban and points.', 'https://www.gesetze-im-internet.de/bkatv_2013/', 'Bußgeldkatalog-Verordnung (BKatV)', null, null, 'die genauen Beträge und Fahrverbotsdauern im aktuellen Katalog', 'the exact amounts and ban lengths in the current catalogue', '2026-09-19'::date, false),
  ('alcohol.drugs', 'alcohol', 5, 'Für Cannabis gilt ein eigener Grenzwert im Blutserum (3,5 ng/ml THC), für andere Drogen der Nachweis selbst; für Fahranfänger und unter 21-Jährige gilt am Steuer ein absolutes Cannabisverbot.', 'Cannabis has its own blood-serum limit (3.5 ng/ml THC), other drugs are penalised on detection alone; for novice drivers and under-21s cannabis at the wheel is banned outright.', 'https://www.gesetze-im-internet.de/stvg/__24a.html', '§ 24a StVG', null, null, 'ob der Grenzwert aus der Novelle von 2024 unverändert gilt', 'whether the limit from the 2024 amendment still applies unchanged', '2026-09-19'::date, false),
  ('alcohol.bicycle', 'alcohol', 6, 'Auch Radfahren betrifft das: ab 1,6 ‰ ist es eine Straftat und kann den Autoführerschein kosten.', 'It applies to cycling too: from 1.6 ‰ it is a criminal offence and can cost you your car licence.', 'https://www.gesetze-im-internet.de/stgb/__316.html', '§ 316 StGB', null, null, null, null, '2026-09-19'::date, false),
  ('toll.no_car_toll', 'toll', 1, 'Für Pkw gibt es in Deutschland keine Maut und keine Vignette. Die geplante Pkw-Maut hat der Europäische Gerichtshof 2019 für unionsrechtswidrig erklärt; eingeführt wurde sie nie.', 'There is no car toll and no vignette in Germany. The planned car toll was ruled contrary to EU law by the Court of Justice in 2019 and never came into force.', 'https://curia.europa.eu/juris/liste.jsf?num=C-591/17', 'EuGH, Urteil vom 18.06.2019, C-591/17', null, null, null, null, '2026-09-19'::date, true),
  ('toll.truck', 'toll', 2, 'Lkw zahlen Maut auf Autobahnen und Bundesstraßen; seit dem 1. Juli 2024 ab 3,5 t technisch zulässiger Gesamtmasse, mit einer Ausnahme für Handwerksbetriebe.', 'Lorries pay toll on motorways and federal roads; since 1 July 2024 from 3.5 t technically permissible mass, with an exemption for craft businesses.', 'https://www.gesetze-im-internet.de/bfstrmg/', 'Bundesfernstraßenmautgesetz (BFStrMG)', null, null, 'die genauen Voraussetzungen der Handwerkerausnahme', 'the exact conditions of the craft-business exemption', '2026-09-19'::date, false),
  ('toll.co2', 'toll', 3, 'Der Mautsatz enthält seit Dezember 2023 einen CO₂-Aufschlag; emissionsfreie Lkw sind begünstigt.', 'Since December 2023 the toll rate includes a CO₂ component; zero-emission lorries are privileged.', 'https://www.gesetze-im-internet.de/bfstrmg/', 'Bundesfernstraßenmautgesetz (BFStrMG)', null, null, null, null, '2026-09-19'::date, false),
  ('toll.collect', 'toll', 4, 'Abgerechnet wird über Toll Collect — On-Board-Unit, App oder Streckenbuchung. Wer ohne Anmeldung fährt, riskiert ein Bußgeld und Nachzahlung.', 'Collection runs through Toll Collect — on-board unit, app or route booking. Driving unregistered risks a fine plus back-payment.', 'https://www.toll-collect.de/', 'Toll Collect GmbH', 'Betreiberin der Lkw-Maut', 'operator of the truck toll', null, null, '2026-09-19'::date, false),
  ('toll.local', 'toll', 5, 'Einzelne Tunnel und Brücken kosten auch Pkw Gebühr, etwa der Warnowtunnel in Rostock und der Herrentunnel in Lübeck.', 'A few tunnels and bridges do charge cars, for example the Warnow tunnel in Rostock and the Herren tunnel in Lübeck.', 'https://www.gesetze-im-internet.de/bfstrmg/', 'BFStrMG', 'Bundesfernstraßen; lokale Betreiber', 'federal trunk roads; local operators', 'aktuelle Preise und ob weitere Bauwerke Gebühr verlangen', 'current prices and whether other structures charge', '2026-09-19'::date, false),
  ('toll.no_city_toll', 'toll', 6, 'Eine City-Maut gibt es in keiner deutschen Stadt: Die einzige Straßenmaut des Bundes ist die Lkw-Maut auf Bundesfernstraßen.', 'No German city charges a congestion charge: the only federal road toll is the lorry toll on federal trunk roads.', 'https://www.gesetze-im-internet.de/bfstrmg/', 'BFStrMG', 'Maut nur für Lkw auf Bundesfernstraßen', 'a toll for lorries on federal trunk roads only', null, null, '2026-09-19'::date, false),
  ('toll.lez_is_not_a_toll', 'toll', 7, 'Die Umweltzone ist kein Bezahlsystem: Die Plakette kauft man einmal, die Einfahrt selbst kostet nichts.', 'The Umweltzone is not a payment scheme: you buy the plaque once, entering costs nothing.', 'https://www.umweltbundesamt.de/themen/luft/luftschadstoffe/feinstaub/umweltzonen-in-deutschland', 'Umweltbundesamt, Umweltzonen in Deutschland', null, null, null, null, '2026-09-19'::date, false),
  ('toll.neighbours_at', 'toll', 8, 'Direkt hinter der Grenze sieht es anders aus: In Österreich braucht auch ein Pkw eine Vignette.', 'Just across the border it differs: in Austria a car needs a vignette too.', 'https://www.asfinag.at/maut-vignette/vignette/', 'ASFINAG, Vignette', 'Österreich', 'Austria', 'Preise und Gültigkeit der österreichischen Vignette (Auskunft: ASFINAG)', 'prices and validity of the Austrian vignette (ASFINAG answers this)', '2026-09-19'::date, false),
  ('toll.neighbours_ch', 'toll', 9, 'Auch die Schweiz verlangt für Autobahnen eine Vignette, von Pkw ebenso.', 'Switzerland requires a motorway vignette as well, from cars too.', 'https://www.ch.ch/de/fahrzeuge-und-verkehr/autobahnvignette/', 'ch.ch, Autobahnvignette', 'Schweiz', 'Switzerland', 'Preis und Gültigkeit der Schweizer Vignette (Auskunft: ch.ch)', 'price and validity of the Swiss vignette (ch.ch answers this)', '2026-09-19'::date, false),
  ('truck_ban.sunday', 'truck_ban', 1, 'Sonntags und an Feiertagen dürfen Lkw über 7,5 t sowie Lkw mit Anhänger von 0 bis 22 Uhr nicht fahren.', 'On Sundays and public holidays, lorries over 7.5 t and lorries with trailers may not drive between 00:00 and 22:00.', 'https://www.gesetze-im-internet.de/stvo_2013/__30.html', '§ 30 Abs. 3 StVO', null, null, null, null, '2026-09-19'::date, true),
  ('truck_ban.cars_free', 'truck_ban', 2, 'Für Pkw, Wohnmobile und Transporter unter 7,5 t gilt das Verbot nicht — der Sonntag ist für sie ein normaler Fahrtag.', 'The ban does not apply to cars, motorhomes and vans under 7.5 t — for them Sunday is an ordinary driving day.', 'https://www.gesetze-im-internet.de/stvo_2013/__30.html', '§ 30 Abs. 3 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('truck_ban.holidays', 'truck_ban', 3, 'Als Feiertage zählen bundesweit Neujahr, Karfreitag, Ostermontag, 1. Mai, Christi Himmelfahrt, Pfingstmontag, 3. Oktober, 25. und 26. Dezember; nur in einzelnen Ländern Fronleichnam (Baden-Württemberg, Bayern, Hessen, Nordrhein-Westfalen, Rheinland-Pfalz, Saarland), der Reformationstag am 31. Oktober (Brandenburg, Bremen, Hamburg, Mecklenburg-Vorpommern, Niedersachsen, Sachsen, Sachsen-Anhalt, Schleswig-Holstein, Thüringen) und Allerheiligen am 1. November (Baden-Württemberg, Bayern, Nordrhein-Westfalen, Rheinland-Pfalz, Saarland).', 'The holidays nationwide are New Year, Good Friday, Easter Monday, 1 May, Ascension, Whit Monday, 3 October, 25 and 26 December; in some federal states only: Corpus Christi (Baden-Württemberg, Bavaria, Hesse, North Rhine-Westphalia, Rhineland-Palatinate, Saarland), Reformation Day on 31 October (Brandenburg, Bremen, Hamburg, Mecklenburg-Western Pomerania, Lower Saxony, Saxony, Saxony-Anhalt, Schleswig-Holstein, Thuringia) and All Saints'' Day on 1 November (Baden-Württemberg, Bavaria, North Rhine-Westphalia, Rhineland-Palatinate, Saarland).', 'https://www.gesetze-im-internet.de/stvo_2013/__30.html', '§ 30 Abs. 4 StVO', null, null, null, null, '2026-10-08'::date, false),
  ('truck_ban.state_holidays', 'truck_ban', 4, 'Ein Feiertag nur einzelner Länder ist nur dort ein Fahrverbotstag: Am 31. Oktober gilt das Lkw-Verbot von 0 bis 22 Uhr in den neun genannten Ländern; in Baden-Württemberg, Bayern, Berlin, Hessen, Nordrhein-Westfalen, Rheinland-Pfalz und im Saarland ist der Tag kein Feiertag nach § 30 Abs. 4 — außer er fällt auf einen Sonntag.', 'A holiday of some federal states only is a ban day only there: on 31 October the lorry ban from 00:00 to 22:00 applies in the nine states named; in Baden-Württemberg, Bavaria, Berlin, Hesse, North Rhine-Westphalia, Rhineland-Palatinate and Saarland the day is not a holiday under § 30(4) — unless it falls on a Sunday.', 'https://www.gesetze-im-internet.de/stvo_2013/__30.html', '§ 30 Abs. 3 und 4 StVO', null, null, null, null, '2026-10-08'::date, false),
  ('truck_ban.unlisted_holidays', 'truck_ban', 5, 'Ein Landesfeiertag, den § 30 Abs. 4 nicht nennt, ist kein Lkw-Fahrverbotstag — etwa in Bayern Heilige Drei Könige (6. Januar), Mariä Himmelfahrt (15. August, in Gemeinden mit überwiegend katholischer Bevölkerung) und in Augsburg das Friedensfest (8. August).', 'A state holiday that § 30(4) does not name is not a lorry-ban day — in Bavaria, for example, Epiphany (6 January), Assumption Day (15 August, in municipalities with a predominantly Catholic population) and in Augsburg the Peace Festival (8 August).', 'https://www.gesetze-bayern.de/Content/Document/BayFTG-1', '§ 30 Abs. 4 StVO; Art. 1 FTG (Bayern)', null, null, null, null, '2026-10-08'::date, false),
  ('truck_ban.summer', 'truck_ban', 6, 'Dazu kommt das Ferienreiseverbot: vom 1. Juli bis 31. August samstags von 7 bis 20 Uhr auf den in der Verordnung genannten Autobahn- und Bundesstraßenabschnitten.', 'On top of that comes the holiday-season ban: 1 July to 31 August, Saturdays 07:00–20:00, on the motorway and federal-road sections listed in the regulation.', 'https://www.gesetze-im-internet.de/ferienreisev/', 'Ferienreiseverordnung', null, null, null, null, '2026-09-19'::date, false),
  ('truck_ban.exemptions', 'truck_ban', 7, 'Ausgenommen sind unter anderem kombinierter Verkehr, frische Milch, frisches Fleisch, frisches Obst und Gemüse — und die dazugehörigen Leerfahrten.', 'Exempt are, among others, combined transport, fresh milk, fresh meat, fresh fruit and vegetables — and the empty runs that belong to them.', 'https://www.gesetze-im-internet.de/stvo_2013/__30.html', '§ 30 Abs. 3 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('truck_ban.enforcement', 'truck_ban', 8, 'Verstöße treffen Fahrer und Unternehmen getrennt; kontrolliert wird an Rastplätzen und Grenzübergängen.', 'Breaches are penalised separately for driver and operator; enforcement happens at rest areas and border crossings.', 'https://www.gesetze-im-internet.de/bkatv_2013/', 'Bußgeldkatalog-Verordnung (BKatV)', null, null, 'die Beträge für Fahrer und Unternehmen', 'the amounts for driver and operator', '2026-09-19'::date, false),
  ('equipment.mandatory', 'equipment', 1, 'Pflicht im Pkw: Warndreieck, Verbandkasten und eine Warnweste.', 'Compulsory in a car: warning triangle, first-aid kit and one high-visibility vest.', 'https://www.gesetze-im-internet.de/stvzo_2012/__53a.html', '§ 53a StVZO', null, null, null, null, '2026-09-19'::date, true),
  ('equipment.first_aid_kit', 'equipment', 2, 'Der Verbandkasten muss der aktuellen DIN 13164 entsprechen und darf nicht abgelaufen sein; die neue Fassung enthält zusätzlich medizinische Masken.', 'The first-aid kit must meet the current DIN 13164 and must not be past its date; the new edition also contains medical masks.', 'https://www.gesetze-im-internet.de/stvzo_2012/__53a.html', '§ 53a StVZO i. V. m. DIN 13164', null, null, 'ob die Masken-Fassung der DIN bereits verbindlich ist oder eine Übergangsfrist läuft', 'whether the mask edition of the DIN is already binding or a transition period applies', '2026-09-19'::date, false),
  ('equipment.vest_count', 'equipment', 3, 'Vorgeschrieben ist eine Warnweste je Fahrzeug. Rat, keine Vorschrift: wer zu mehreren aussteigt, nimmt besser eine pro Person mit, griffbereit im Innenraum statt im Kofferraum.', 'One vest per vehicle is required. Advice, not law: if several of you may get out, carry one each, within reach inside the car rather than in the boot.', 'https://www.gesetze-im-internet.de/stvzo_2012/__53a.html', '§ 53a Abs. 2 StVZO', null, null, null, null, '2026-09-19'::date, false),
  ('equipment.documents', 'equipment', 4, 'Mitführen: Führerschein, Zulassungsbescheinigung Teil I und den Versicherungsnachweis; bei Fahrzeugen aus Nicht-EU-Staaten gegebenenfalls die Grüne Karte.', 'Carry: driving licence, vehicle registration document (part I) and proof of insurance; for vehicles from outside the EU, the Green Card where applicable.', 'https://www.gesetze-im-internet.de/fev_2010/__29.html', '§ 29 FeV; § 11 FZV', null, null, null, null, '2026-09-19'::date, false),
  ('equipment.foreign_licence', 'equipment', 5, 'EU- und EWR-Führerscheine gelten unbefristet. Führerscheine aus anderen Staaten gelten für Besucher befristet; ein internationaler Führerschein oder eine Übersetzung wird empfohlen.', 'EU and EEA licences are valid without limit. Licences from other countries are valid for visitors for a limited period; an international driving permit or a translation is recommended.', 'https://www.gesetze-im-internet.de/fev_2010/__29.html', '§ 29 FeV', null, null, 'die genaue Frist und ab wann sie läuft (Wohnsitzbegründung)', 'the exact period and when it starts (taking up residence)', '2026-09-19'::date, false),
  ('equipment.child_seats', 'equipment', 6, 'Kinder unter 12 Jahren, die kleiner als 150 cm sind, brauchen einen geeigneten Kindersitz.', 'Children under 12 who are shorter than 150 cm need a suitable child restraint.', 'https://www.gesetze-im-internet.de/stvo_2013/__21.html', '§ 21 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('equipment.phone', 'equipment', 7, 'Das Handy darf am Steuer nur freihändig benutzt werden — in die Hand nehmen kostet Bußgeld und einen Punkt, auch im Stau.', 'The phone may only be used hands-free — picking it up costs a fine and a point, in a traffic jam too.', 'https://www.gesetze-im-internet.de/stvo_2013/__23.html', '§ 23 Abs. 1a StVO', null, null, 'der genaue Betrag im aktuellen Bußgeldkatalog', 'the exact amount in the current fines catalogue', '2026-09-19'::date, false),
  ('equipment.not_required', 'equipment', 8, 'Nicht vorgeschrieben sind Alkoholtester, Feuerlöscher oder Ersatzlampen — anders als in manchen Nachbarländern.', 'Not required: breathalyser, fire extinguisher or spare bulbs — unlike in some neighbouring countries.', 'https://www.gesetze-im-internet.de/stvzo_2012/__53a.html', '§ 53a StVZO', 'Umkehrschluss', 'by inference', null, null, '2026-09-19'::date, false),
  ('equipment.lights', 'equipment', 9, 'Tagfahrlicht ist für Pkw nicht vorgeschrieben, bei Dunkelheit, Nebel, Regen und Schneefall aber Abblendlicht Pflicht; Krafträder fahren immer mit Licht.', 'Daytime running lights are not compulsory for cars, but dipped beam is required in darkness, fog, rain and snowfall; motorcycles always run with lights.', 'https://www.gesetze-im-internet.de/stvo_2013/__17.html', '§ 17 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('equipment.plate', 'equipment', 10, 'Ein EU-Kennzeichen mit Länderkürzel genügt als Nationalitätskennzeichen; sonst gehört ein Länderaufkleber ans Heck.', 'An EU plate with the country code serves as the nationality mark; otherwise a country sticker belongs on the back.', 'https://www.gesetze-im-internet.de/fev_2010/__29.html', '§ 29 FeV; Wiener Übereinkommen über den Straßenverkehr', null, null, null, null, '2026-09-19'::date, false),
  ('emergency.numbers', 'emergency', 1, '112 ruft Rettungsdienst und Feuerwehr (europaweit), 110 die Polizei — kostenlos aus jedem Netz, auch ohne Guthaben.', '112 reaches ambulance and fire service (Europe-wide), 110 the police — free from any network, credit or not.', 'https://www.gesetze-im-internet.de/notrufv/', 'Notrufverordnung (NotrufV)', null, null, null, null, '2026-09-19'::date, true),
  ('emergency.rettungsgasse', 'emergency', 2, 'Rettungsgasse: Sobald der Verkehr auf Autobahnen und Außerortsstraßen mit mindestens zwei Spuren je Richtung stockt, ist zwischen der äußerst linken und der daneben liegenden Spur eine Gasse frei zu halten — sofort, nicht erst wenn das Blaulicht kommt.', 'Rescue lane: as soon as traffic slows on a motorway or rural road with at least two lanes per direction, keep a lane free between the leftmost lane and the one beside it — immediately, not once the blue lights arrive.', 'https://www.gesetze-im-internet.de/stvo_2013/__11.html', '§ 11 Abs. 2 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('emergency.rettungsgasse_penalty', 'emergency', 3, 'Keine Rettungsgasse zu bilden kostet ein dreistelliges Bußgeld, Punkte und in der Regel ein Fahrverbot; durch die Rettungsgasse zu fahren ebenso.', 'Failing to form the rescue lane costs a three-figure fine, points and usually a driving ban; using the lane to get ahead does too.', 'https://www.gesetze-im-internet.de/bkatv_2013/', 'Bußgeldkatalog-Verordnung (BKatV)', null, null, 'die genauen Beträge und die Dauer des Fahrverbots', 'the exact amounts and the length of the ban', '2026-09-19'::date, false),
  ('emergency.breakdown', 'emergency', 4, 'Panne: Warnblinker an, Warnweste anziehen, wenn möglich auf den Seitenstreifen, Warndreieck deutlich hinter dem Fahrzeug aufstellen (auf der Autobahn rund 150–200 m) und hinter die Leitplanke gehen.', 'Breakdown: hazard lights on, put on the vest, pull onto the hard shoulder if you can, place the triangle well behind the car (about 150–200 m on the Autobahn) and wait behind the barrier.', 'https://www.gesetze-im-internet.de/stvo_2013/__15.html', '§ 15 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('emergency.call_boxes', 'emergency', 5, 'An Autobahnen stehen orangefarbene Notrufsäulen; die kleinen schwarzen Pfeile auf den Leitpfosten zeigen zur nächsten. Sie funktionieren auch ohne Mobilfunknetz.', 'Orange emergency call boxes stand along motorways; the small black arrows on the roadside posts point to the nearest one. They work without mobile coverage.', 'https://www.autobahn.de/', 'Autobahn GmbH des Bundes', null, null, 'der übliche Abstand zwischen zwei Notrufsäulen', 'the usual spacing between two call boxes', '2026-09-19'::date, false),
  ('emergency.roadside_assistance', 'emergency', 6, 'Pannenhilfe holen die Automobilclubs, der ADAC auch für Nichtmitglieder gegen Gebühr; Mietwagen haben meist eine eigene Nummer in den Papieren.', 'Roadside assistance comes from the automobile clubs; the ADAC serves non-members for a fee. A rental car usually has its own number in the documents.', 'https://www.adac.de/services/pannenhilfe/', 'ADAC Pannenhilfe', null, null, 'die aktuellen Rufnummern im In- und Ausland', 'the current phone numbers at home and from abroad', '2026-09-19'::date, false),
  ('emergency.after_a_crash', 'emergency', 7, 'Nach einem Unfall: Unfallstelle sichern, Erste Hilfe leisten — unterlassene Hilfeleistung ist strafbar —, bei Verletzten oder Streit die Polizei rufen, Personalien und Versicherung austauschen.', 'After a crash: secure the scene, give first aid — failing to help is a criminal offence — call the police if anyone is hurt or you disagree, and exchange details and insurance.', 'https://www.gesetze-im-internet.de/stgb/__323c.html', '§ 34 StVO; § 323c StGB', null, null, null, null, '2026-09-19'::date, false),
  ('emergency.hit_and_run', 'emergency', 8, 'Einfach weiterfahren ist Unfallflucht und eine Straftat — auch bei einem Kratzer auf einem Parkplatz. Ein Zettel an der Scheibe genügt nicht.', 'Driving away is hit-and-run and a criminal offence — even for a scratch in a car park. A note under the wiper is not enough.', 'https://www.gesetze-im-internet.de/stgb/__142.html', '§ 142 StGB', null, null, null, null, '2026-09-19'::date, false),
  ('emergency.hard_shoulder', 'emergency', 9, 'Der Seitenstreifen ist nur für den Notfall da. Liegenbleiben mit leerem Tank oder leerer Batterie gilt als vermeidbar und wird geahndet.', 'The hard shoulder is for emergencies only. Stopping because you ran out of fuel or charge counts as avoidable and is penalised.', 'https://www.gesetze-im-internet.de/stvo_2013/__18.html', '§ 18 StVO', null, null, null, null, '2026-09-19'::date, false),
  ('ev.e_kennzeichen', 'ev', 1, 'Das E-Kennzeichen ist ein Nummernschild mit angehängtem „E“. Es bekommen reine Elektro- und Brennstoffzellenautos sowie Plug-in-Hybride, die die Grenzwerte des Elektromobilitätsgesetzes erfüllen.', 'The E-Kennzeichen is a number plate with an "E" at the end. Battery-electric and fuel-cell cars get it, as do plug-in hybrids that meet the thresholds in the Electric Mobility Act.', 'https://www.gesetze-im-internet.de/emog/', 'Elektromobilitätsgesetz (EmoG)', null, null, 'der aktuelle Reichweiten-/CO₂-Grenzwert für Plug-in-Hybride und wie ausländische E-Fahrzeuge gekennzeichnet werden', 'the current range/CO₂ threshold for plug-in hybrids and how foreign EVs are marked', '2026-09-19'::date, true),
  ('ev.privileges_per_city', 'ev', 2, 'Die Vorteile — kostenloses oder ermäßigtes Parken, Busspur, Ausnahmen von Zufahrtsverboten — gewährt jede Kommune einzeln. Es gibt kein bundesweites Recht auf kostenloses Parken: Es gilt nur dort, wo ein Zusatzzeichen „Elektrofahrzeuge frei“ steht.', 'The privileges — free or reduced parking, bus lanes, exemptions from access bans — are granted by each municipality separately. There is no nationwide right to park for free: it applies only where a supplementary sign says "electric vehicles exempt".', 'https://www.gesetze-im-internet.de/emog/__3.html', '§ 3 EmoG', null, null, 'welche Stadt derzeit was gewährt — konkret auch, ob München kostenloses Parken für E-Kennzeichen gewährt', 'which city currently grants what — in particular whether Munich grants free parking for E plates', '2026-09-19'::date, false),
  ('ev.green_plakette', 'ev', 3, 'Auch ein Elektroauto braucht für die Umweltzone die grüne Plakette an der Scheibe — emissionsfrei heißt nicht plakettenfrei.', 'An electric car needs the green plaque on the windscreen for the Umweltzone too — zero-emission does not mean plaque-free.', 'https://www.gesetze-im-internet.de/bimschv_35_2007/', '35. BImSchV', null, null, null, null, '2026-09-19'::date, false),
  ('ev.adhoc_card', 'ev', 4, 'Ad-hoc-Laden ist ein Recht: An öffentlich zugänglichen Ladepunkten kann man ohne Vertrag und ohne App laden. Neue Punkte ab 50 kW, die seit dem 13. April 2024 in Betrieb gehen, müssen ein Karten-Lesegerät für Debit- und Kreditkarten haben.', 'Ad-hoc charging is a right: at publicly accessible points you can charge with no contract and no app. New points from 50 kW commissioned since 13 April 2024 must have a card reader for debit and credit cards.', 'https://eur-lex.europa.eu/eli/reg/2023/1804/oj', 'Art. 5 VO (EU) 2023/1804 (AFIR)', null, null, 'die Frist, bis zu der ältere Punkte ab 50 kW nachgerüstet sein müssen', 'the deadline by which existing points from 50 kW must be retrofitted', '2026-09-19'::date, false),
  ('ev.adhoc_older_points', 'ev', 5, 'Ältere Säulen bieten Ad-hoc-Laden oft per QR-Code und Webbezahlung an; die Ladesäulenverordnung verlangt bei neuen Punkten mindestens ein gängiges kartenbasiertes Bezahlsystem.', 'Older posts often offer ad-hoc charging via QR code and web payment; the German charging-point regulation requires at least one common card-based payment system at new points.', 'https://www.gesetze-im-internet.de/lsv_2016/', 'Ladesäulenverordnung (LSV)', null, null, 'ab welchem Datum die LSV-Kartenpflicht für neue Punkte gilt', 'from which date the card requirement applies to new points', '2026-09-19'::date, false),
  ('ev.plugs', 'ev', 6, 'Stecker: Typ 2 für Wechselstrom (bis 22 kW), CCS2 für Gleichstrom-Schnellladen, CHAdeMO nur noch selten. Ein europäisches Fahrzeug passt ohne Adapter; das eigene Typ-2-Kabel gehört ins Auto, weil AC-Säulen oft keins haben.', 'Plugs: Type 2 for AC (up to 22 kW), CCS2 for DC fast charging, CHAdeMO now rare. A European car fits without an adapter; carry your own Type 2 cable, because AC posts often have none.', 'https://eur-lex.europa.eu/eli/reg/2023/1804/oj', 'Art. 4 und Anhang II VO (EU) 2023/1804 (AFIR)', null, null, null, null, '2026-09-19'::date, false),
  ('ev.price_shape', 'ev', 7, 'Der Preis wird je Kilowattstunde ausgewiesen und geeicht abgerechnet; dazu kann eine Blockiergebühr je Minute kommen, wenn das Auto nach dem Laden stehen bleibt.', 'The price is shown per kilowatt-hour and metered under calibration law; a blocking fee per minute can be added if the car stays plugged in after charging.', 'https://www.gesetze-im-internet.de/lsv_2016/', 'Ladesäulenverordnung (LSV); Eichrecht', null, null, null, null, '2026-09-19'::date, false),
  ('ev.roaming', 'ev', 8, 'Mit der Ladekarte eines Anbieters lädt man über Roaming auch an fremden Säulen — dann gilt der Tarif der Karte, nicht der Aushang. Ad-hoc mit Karte ist oft teurer, aber immer möglich.', 'With one provider''s charging card you can roam onto other operators'' posts — then the card''s tariff applies, not the one on the post. Ad-hoc by bank card is often dearer but always available.', 'https://www.gesetze-im-internet.de/lsv_2016/', 'Ladesäulenverordnung (LSV)', null, null, null, null, '2026-09-19'::date, false),
  ('ev.etiquette', 'ev', 9, 'Ladeplätze sind mit Zeichen 314 und dem Sinnbild Elektrofahrzeug ausgewiesen: Dort darf nur ein ladendes E-Auto stehen. Nach dem Laden wegfahren, Kabel aufräumen, fremde Ladevorgänge nicht abbrechen.', 'Charging bays carry sign 314 with the electric-vehicle symbol: only a charging EV may stand there. Move on when you are done, tidy the cable, never stop someone else''s session.', 'https://www.gesetze-im-internet.de/stvo_2013/anlage_3.html', 'StVO Anlage 3, Zeichen 314 mit Sinnbild Elektrofahrzeug', null, null, null, null, '2026-09-19'::date, false),
  ('ev.emergency', 'ev', 10, 'Bei Panne oder Unfall gilt dasselbe wie sonst: 112, Warnweste, Warndreieck. Der Rettungsdienst sollte wissen, dass es ein Elektroauto ist; orangefarbene Hochvoltleitungen nicht berühren. Mit leerer Batterie auf der Autobahn liegen zu bleiben gilt als vermeidbar.', 'In a breakdown or crash the rules are the same: 112, vest, triangle. Tell the emergency services it is an electric car; never touch the orange high-voltage cables. Running the battery flat on the Autobahn counts as an avoidable stop.', 'https://www.gesetze-im-internet.de/stvo_2013/__15.html', '§ 15 StVO; Rettungskarte des Herstellers', null, null, null, null, '2026-09-19'::date, false);
