  ('berlin', 'Berlin', array['berlin']::text[], array['11000000']::text[], 'green', true, null, '2026-10-22'::date, 'https://gis.uba.de/website/umweltzonen/index.php#uwz', 'Umweltbundesamt, Liste der Umweltzonen in Deutschland'),
